/// How an operation picks its location (spec 06 §1.1).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Scope {
    /// Global services only.
    G,
    /// Request location (`location[directory]` / `x-opencode-directory` / cwd); must exist.
    L,
    /// Session location (path `sessionID`, validated `^ses`).
    S,
    /// Like S, but `sessionID == "global"` selects the request location.
    F,
    /// Handler resolves the location itself.
    H,
}

/// Success envelope of an operation (spec 06 §2.2).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Envelope {
    /// `{location:{directory}, data}`
    Location,
    /// `{data}`
    Data,
    /// The body as-is.
    Bare,
    /// `204` with an empty body.
    NoContent,
    /// Raw / streaming / WebSocket response.
    Raw,
}

